import test from 'node:test';
import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { CODE_JOBS, classifyPaths, isVersionOnly, scopeFromGit, selectScope } from './ci-scope.mjs';

const jobs = scope => [...scope.jobs].sort();

const lock = (agent, service, extra = '') => [
  '# This file is automatically @generated by Cargo.',
  'version = 4',
  '',
  '[[package]]',
  'name = "reqwest"',
  'version = "0.13.5"',
  'source = "registry+https://github.com/rust-lang/crates.io-index"',
  '',
  '[[package]]',
  'name = "senlun-agent"',
  `version = "${agent}"`,
  'dependencies = [',
  ' "reqwest",',
  ' "senlun-protocol",',
  ']',
  '',
  '[[package]]',
  'name = "senlun-protocol"',
  `version = "${service}"`,
  '',
  '[[package]]',
  'name = "senlun-service"',
  `version = "${service}"`,
  'dependencies = [',
  ` "senlun-protocol",${extra}`,
  ']',
  '',
].join('\n');

const packageJson = (version, extra = {}) => JSON.stringify({ name: '@petauron/senlun-web', version, dependencies: { vue: '^3.5.45', ...extra } }, null, 2);
const packageLock = version => JSON.stringify({ name: '@petauron/senlun-web', version, lockfileVersion: 3, packages: { '': { name: '@petauron/senlun-web', version }, 'node_modules/vue': { version: '3.5.45' } } }, null, 2);

function release(overrides = {}) {
  const base = {
    '.release-please-manifest.json': '{\n  ".": "0.2.0",\n  "crates": "0.2.0"\n}\n',
    'version.txt': '0.2.0\n',
    'crates/senlun-agent/version.txt': '0.2.0\n',
    'CHANGELOG.md': '# Changelog\n',
    'crates/senlun-agent/CHANGELOG.md': '# Changelog\n',
    'Cargo.toml': '[workspace.package]\nversion = "0.2.0"\nedition = "2024"\n',
    'crates/senlun-agent/Cargo.toml': '[package]\nname = "senlun-agent"\nversion = "0.2.0"\n',
    'Cargo.lock': lock('0.2.0', '0.2.0'),
    'web/package.json': packageJson('0.2.0'),
    'web/package-lock.json': packageLock('0.2.0'),
  };
  const head = {
    '.release-please-manifest.json': '{\n  ".": "0.2.1",\n  "crates": "0.2.1"\n}\n',
    'version.txt': '0.2.1\n',
    'crates/senlun-agent/version.txt': '0.2.1\n',
    'CHANGELOG.md': '# Changelog\n\n## 0.2.1\n\n* fix\n',
    'crates/senlun-agent/CHANGELOG.md': '# Changelog\n\n## 0.2.1\n',
    'Cargo.toml': '[workspace.package]\nversion = "0.2.1"\nedition = "2024"\n',
    'crates/senlun-agent/Cargo.toml': '[package]\nname = "senlun-agent"\nversion = "0.2.1"\n',
    'Cargo.lock': lock('0.2.1', '0.2.1'),
    'web/package.json': packageJson('0.2.1'),
    'web/package-lock.json': packageLock('0.2.1'),
    ...overrides,
  };
  const paths = Object.keys(head).filter(path => head[path] !== base[path]);
  const read = (revision, path) => (revision === 'base' ? base : head)[path] ?? null;
  return { paths, read };
}

test('documentation, deploy tooling and release-only packaging select no code jobs', () => {
  const scope = classifyPaths(['docs/MONITORING.md', 'README.md', 'deploy/install-systemd.sh', '.env.example', 'compat/luminaplus/LICENSE', 'scripts/benchmark-storage.py', 'scripts/brand-names.test.mjs']);
  assert.deepEqual(jobs(scope), []);
});

test('Web source changes run Web static checks and browser tests only', () => {
  assert.deepEqual(jobs(classifyPaths(['web/src/components/NodeIpScores.vue'])), ['e2e', 'web']);
  assert.deepEqual(jobs(classifyPaths(['web/e2e/monitoring.spec.ts'])), ['e2e', 'web']);
  assert.deepEqual(jobs(classifyPaths(['web/THIRD_PARTY_NOTICES.md', 'web/LICENSE.lucide'])), ['web']);
});

test('single-crate changes narrow Rust checks without dropping browser or Debian runtime coverage', () => {
  const agent = classifyPaths(['crates/senlun-agent/src/ip_unlock.rs']);
  assert.deepEqual(jobs(agent), ['container', 'e2e', 'rust']);
  assert.equal(agent.rustPackages, '-p senlun-agent');
  assert.equal(classifyPaths(['crates/senlun-service/src/control.rs']).rustPackages, '-p senlun-service');
  assert.equal(classifyPaths(['crates/senlun-agent/src/main.rs', 'crates/senlun-service/src/lib.rs']).rustPackages, '--workspace');
  assert.equal(classifyPaths(['crates/senlun-protocol/src/lib.rs']).rustPackages, '--workspace');
  assert.equal(classifyPaths(['crates/senlun-agent/src/main.rs', 'rustfmt.toml']).rustPackages, '-p senlun-agent');
});

test('dependency and toolchain changes add security and source image coverage', () => {
  assert.deepEqual(jobs(classifyPaths(['Cargo.lock'])), ['container', 'e2e', 'rust', 'security', 'source_docker']);
  assert.equal(classifyPaths(['Cargo.lock', 'crates/senlun-agent/src/main.rs']).rustPackages, '--workspace');
  assert.deepEqual(jobs(classifyPaths(['crates/senlun-service/Cargo.toml'])), ['container', 'e2e', 'rust', 'security', 'source_docker']);
  assert.deepEqual(jobs(classifyPaths(['web/package-lock.json'])), ['container', 'e2e', 'rust', 'security', 'source_docker', 'web']);
  assert.deepEqual(jobs(classifyPaths(['deny.toml', 'RUST_THIRD_PARTY_LICENSES.html'])), ['rust', 'security']);
});

test('test-consumed assets and Web-dependent release tests keep their coverage', () => {
  const theme = classifyPaths(['compat/luminaplus/LuminaPlus-v1.3.5-senlun.zip']);
  assert.deepEqual(jobs(theme), ['container', 'e2e', 'rust']);
  assert.equal(theme.rustPackages, '-p senlun-service');
  assert.deepEqual(jobs(classifyPaths(['scripts/release-source.mjs'])), ['web']);
});

test('container inputs select only their own image checks', () => {
  assert.deepEqual(jobs(classifyPaths(['.dockerignore'])), ['source_docker']);
  assert.deepEqual(jobs(classifyPaths(['scripts/build-linux-release.sh'])), ['container', 'rust']);
});

test('files asserted by release-source tests select the Web job that runs them', () => {
  assert.deepEqual(jobs(classifyPaths(['scripts/publish-agent-draft.sh'])), ['web']);
  assert.deepEqual(jobs(classifyPaths(['release-please-config.json'])), ['rust', 'web']);
  assert.deepEqual(jobs(classifyPaths(['Dockerfile'])), ['source_docker', 'web']);
  assert.deepEqual(jobs(classifyPaths(['Dockerfile.release'])), ['container', 'web']);
});

test('workflow, classifier and unknown paths fail closed to the complete suite', () => {
  for (const path of ['.github/workflows/ci.yml', 'scripts/ci-scope.mjs', '.gitignore', 'new-top-level-file.txt', 'crates/new-crate/src/lib.rs']) {
    const scope = classifyPaths(['docs/README.md', path]);
    assert.deepEqual(jobs(scope), [...CODE_JOBS].sort(), path);
    assert.equal(scope.rustPackages, '--workspace');
  }
});

test('a Release Please version bump runs only version and security checks', () => {
  const { paths, read } = release();
  assert.equal(isVersionOnly(paths, read), true);
  assert.deepEqual(jobs(selectScope({ paths, read })), ['security', 'version']);
  // A fresh exact-SHA check still runs on main even when the PR tree matched.
  assert.deepEqual(jobs(selectScope({ paths, read, verifiedTree: true })), ['security', 'version']);
});

test('version bumps carrying any other change fall back to path classification', () => {
  const dependency = release({ 'Cargo.lock': lock('0.2.1', '0.2.1', '\n "reqwest",') });
  assert.equal(isVersionOnly(dependency.paths, dependency.read), false);
  assert.ok(selectScope(dependency).jobs.has('rust'));

  const thirdParty = release({ 'Cargo.lock': lock('0.2.1', '0.2.1').replace('version = "0.13.5"', 'version = "0.13.6"') });
  assert.equal(isVersionOnly(thirdParty.paths, thirdParty.read), false);

  const npm = release({ 'web/package.json': packageJson('0.2.1', { axios: '^1.0.0' }) });
  assert.equal(isVersionOnly(npm.paths, npm.read), false);

  const cargo = release({ 'Cargo.toml': '[workspace.package]\nversion = "0.2.1"\nedition = "2021"\n' });
  assert.equal(isVersionOnly(cargo.paths, cargo.read), false);

  const code = release();
  code.paths.push('crates/senlun-service/src/lib.rs');
  assert.equal(isVersionOnly(code.paths, code.read), false);

  const noManifest = release();
  noManifest.paths.splice(noManifest.paths.indexOf('.release-please-manifest.json'), 1);
  assert.equal(isVersionOnly(noManifest.paths, noManifest.read), false);

  const deleted = release({ 'version.txt': undefined });
  assert.equal(isVersionOnly([...deleted.paths, 'version.txt'], deleted.read), false);

  const extraBlock = release({ 'Cargo.lock': `${lock('0.2.1', '0.2.1')}\n[[package]]\nname = "senlun-extra"\nversion = "0.2.1"\n` });
  assert.equal(isVersionOnly(extraBlock.paths, extraBlock.read), false);
});

test('a verified identical tree skips repeated code checks', () => {
  const read = () => null;
  assert.deepEqual(jobs(selectScope({ paths: ['crates/senlun-service/src/lib.rs'], read, verifiedTree: true })), []);
});

// Regression against real history (CI checks out full history; skipped otherwise).
const hasCommit = (sha) => {
  try {
    execFileSync('git', ['cat-file', '-e', `${sha}^{commit}`], { stdio: 'ignore' });
    return true;
  }
  catch {
    return false;
  }
};
const history = {
  release020: ['496a67ee7e1dbe16a02984353720890b4eb96650', 'c1501646372b769322172dd1fb736ae57dafda33'],
  feature287: ['1c9e19d177e79ccac6b62ac680a65a937a87d5f0', '496a67ee7e1dbe16a02984353720890b4eb96650'],
  deps289: ['cfc0506589293eea23f190128f06082c94db9539', '1c9e19d177e79ccac6b62ac680a65a937a87d5f0'],
};
const historyAvailable = Object.values(history).flat().every(hasCommit);

test('real v0.2.0 history classifies releases, features and dependency fixes correctly', { skip: !historyAvailable && 'full Git history unavailable' }, () => {
  assert.deepEqual(jobs(scopeFromGit(...history.release020)), ['security', 'version']);
  const feature = scopeFromGit(...history.feature287);
  assert.deepEqual(jobs(feature), ['container', 'e2e', 'rust', 'web']);
  assert.equal(feature.rustPackages, '--workspace');
  assert.deepEqual(jobs(scopeFromGit(...history.deps289)), ['container', 'e2e', 'rust', 'security', 'source_docker']);
});
